#!/bin/bash
# Repo cleanup: remove the partner track's experiment files, archive
# superseded work, and renumber the pipeline to run 01..10 with no gaps.
#
# Safe to re-run. Every written file is verified by sha256.
#
# Usage:  bash install_cleanup.sh [target-dir]      (default: $HOME/NLP_Lab)

set -euo pipefail
TARGET="${1:-$HOME/NLP_Lab}"
STAMP="$(date +%Y%m%d-%H%M%S)"
[ -d "$TARGET" ] || { echo "FATAL: no such directory: $TARGET"; exit 1; }
[ -d "$TARGET/scripts" ] && [ -d "$TARGET/src/probe_extraction" ] || {
  echo "FATAL: $TARGET does not look like the NLP_Lab repo."; exit 1; }
cd "$TARGET"
echo "Cleaning up: $TARGET"; echo ""
N_DEL=0; N_MV=0; N_NEW=0; N_UPD=0; N_SAME=0

write_file() {  # $1 path, $2 sha256, $3 mode
  local path="$1" want="$2" mode="$3" tmp
  mkdir -p "$(dirname "$path")"
  tmp="$(mktemp)"
  base64 --decode > "$tmp"
  local got; got="$(sha256sum "$tmp" | cut -d" " -f1)"
  [ "$got" = "$want" ] || { echo "  FATAL: $path decoded to $got"; rm -f "$tmp"; exit 1; }
  if [ -f "$path" ]; then
    local cur; cur="$(sha256sum "$path" | cut -d" " -f1)"
    if [ "$cur" = "$want" ]; then
      rm -f "$tmp"; N_SAME=$((N_SAME+1)); return 0; fi
    cp -p "$path" "${path}.bak.${STAMP}"
    echo "  updated  $path"; N_UPD=$((N_UPD+1))
  else
    echo "  new      $path"; N_NEW=$((N_NEW+1))
  fi
  cat "$tmp" > "$path"; rm -f "$tmp"; chmod "$mode" "$path"
}

echo "--- 1. remove partner-track experiment files and spent installers ---"
